// ============================================
// NODO: Check Duplicate Convenio
// FUNCION: Verificar si ya existe un convenio con el mismo codigo_regcon
// NOTA: Solo aplica para flujo BOE/manual que trae codigo_regcon
//       El flujo de upload de usuario NO trae codigo_regcon
// ============================================

const body = $input.first().json.body;
const codigoRegcon = body.codigo_regcon;

// Si no hay codigo_regcon, es un upload de usuario -> continuar sin verificar
// Preservamos la estructura original del body para compatibilidad
if (!codigoRegcon) {
  return [{
    json: {
      check_result: 'skip',
      body: body  // Preservar estructura para nodos siguientes
    }
  }];
}

// Si hay codigo_regcon, consultar Supabase
const supabaseUrl = $credentials.supabaseApi.url;
const supabaseKey = $credentials.supabaseApi.serviceRoleKey;

const response = await fetch(
  `${supabaseUrl}/rest/v1/convenios?codigo_regcon=eq.${codigoRegcon}&select=id,nombre,estado,codigo_regcon`,
  {
    method: 'GET',
    headers: {
      'apikey': supabaseKey,
      'Authorization': `Bearer ${supabaseKey}`,
      'Content-Type': 'application/json'
    }
  }
);

const existingConvenios = await response.json();

if (existingConvenios.length > 0) {
  return [{
    json: {
      check_result: 'duplicate',
      existing_convenio: existingConvenios[0],
      body: body
    }
  }];
}

return [{
  json: {
    check_result: 'new',
    body: body  // Preservar estructura para nodos siguientes
  }
}];

// ============================================
// NODO: Respond Duplicate Convenio
// FUNCION: Responder que el convenio ya existe
// ============================================

const data = $input.first().json;
const existingConvenio = data.existing_convenio;
const body = data.body;

return [{
  json: {
    status: 'duplicate',
    message: 'El convenio ya existe en el sistema',
    existing_convenio: {
      id: existingConvenio.id,
      nombre: existingConvenio.nombre,
      estado: existingConvenio.estado,
      codigo_regcon: existingConvenio.codigo_regcon
    },
    requested: {
      nombre: body.nombre,
      codigo_regcon: body.codigo_regcon
    },
    action_required: 'none'
  }
}];

// Limpiar contador de reintentos cuando el job completa exitosamente
const markdownResult = $input.first().json;

// Obtener job ID del nodo de status check
const statusCheck = $('Check LlamaParse Status').first();
if (statusCheck && statusCheck.json && statusCheck.json.id) {
  const jobId = statusCheck.json.id;

  // Limpiar contador de este job en static data
  const staticData = $getWorkflowStaticData('node');
  if (staticData.llamaparseRetries && staticData.llamaparseRetries[jobId]) {
    console.log(`Limpiando contador de reintentos para job ${jobId}`);
    delete staticData.llamaparseRetries[jobId];
  }
}

// Pasar los datos sin modificar
return {
  json: markdownResult
};

// Controlar límite de reintentos para LlamaParse polling
const MAX_RETRIES = 10;

// Obtener datos actuales del status check
const currentData = $input.first().json;
const jobId = currentData.id;

if (!jobId) {
  throw new Error('No se encontró job ID en la respuesta de LlamaParse');
}

// Obtener workflow static data para almacenamiento persistente
const staticData = $getWorkflowStaticData('node');

// Inicializar estructura de contadores si no existe
if (!staticData.llamaparseRetries) {
  staticData.llamaparseRetries = {};
}

// Obtener o inicializar contador para este job
let retryCount = staticData.llamaparseRetries[jobId] || 0;

// Incrementar contador
retryCount++;
staticData.llamaparseRetries[jobId] = retryCount;

console.log(`Reintento LlamaParse #${retryCount}/${MAX_RETRIES} - Job: ${jobId} - Status: ${currentData.status}`);

// Si excedemos el límite, lanzar error
if (retryCount > MAX_RETRIES) {
  // Limpiar contador antes de fallar
  delete staticData.llamaparseRetries[jobId];

  throw new Error(
    `LlamaParse polling excedió el límite de ${MAX_RETRIES} reintentos. ` +
    `Último status: ${currentData.status}. Job ID: ${jobId}`
  );
}

// Pasar los datos sin modificar (el contador está en static data)
return {
  json: currentData
};

// ============================================
// NODO: Chunk Markdown
// WORKFLOW: Workrules Convenios - Indexer
// TIPO: Code (JavaScript) v2
// ============================================
// I1.10: Chunking por páginas. Cada chunk lleva `metadata.pagina` (1-indexed)
// con la página del PDF original donde empieza. Los chunks NO cruzan páginas:
// si un artículo se reparte entre dos páginas, se generan dos chunks (y la
// expansión por vecinos en query time se encarga de juntarlos).
// La sección y el artículo SÍ se heredan entre páginas.
// ============================================

// ============================================
// CONFIGURACIÓN
// ============================================
const TARGET_TOKENS = 450; // Target ideal
const MAX_TOKENS = 600; // Límite duro
const MIN_TOKENS = 100; // Mínimo para chunk válido (contenido genérico)
const MIN_TOKENS_ARTICULO = 25; // Mínimo para artículos (pueden ser muy cortos pero son unidades semánticas)
const OVERLAP_CHARS = 200; // ~50 tokens de overlap

// ============================================
// FUNCIONES AUXILIARES
// ============================================

function estimateTokens(text) {
  if (!text) return 0;
  const words = text.split(/\s+/).length;
  const chars = text.length;
  return Math.round((chars / 4 + words * 1.3) / 2);
}

function detectChunkType(content) {
  if (/\|.*\|/.test(content) && /salario|retribuc|sueldo|euro|€/i.test(content))
    return 'tabla_salarial';
  if (/\|.*\|/.test(content)) return 'tabla';
  if (/se entiende por|a los efectos|definición|concepto/i.test(content))
    return 'definicion';
  if (
    /procedimiento|solicitud|plazo de|días (hábiles|naturales)/i.test(content)
  )
    return 'procedimiento';
  if (/jornada|horario|descanso|vacaciones|permiso/i.test(content))
    return 'jornada';
  if (/falta (leve|grave|muy grave)|sanción|despido/i.test(content))
    return 'sanciones';
  return 'normativa';
}

function extractSeccion(content, previousSeccion) {
  const match = content.match(/^##\s+(.+)$/m);
  if (match) return match[1].trim();
  return previousSeccion || null;
}

/**
 * Detecta si estamos en una sección de ANEXO (no tiene artículos numerados)
 * Los anexos incluyen: tablas salariales, disposiciones, categorías profesionales, etc.
 */
function isAnexoSection(seccion) {
  if (!seccion) return false;
  const seccionLower = seccion.toLowerCase();
  return (
    seccionLower.includes('anexo') ||
    seccionLower.includes('tabla') ||
    seccionLower.includes('disposicion') ||
    seccionLower.includes('clasificación profesional') ||
    seccionLower.includes('clasificacion profesional') ||
    seccionLower.includes('categorías profesionales') ||
    seccionLower.includes('categorias profesionales') ||
    seccionLower.includes('niveles retributivos') ||
    seccionLower.includes('grupos profesionales')
  );
}

function extractArticulo(content, previousArticulo, currentSeccion) {
  // ============================================
  // EXTRACCIÓN DE ARTÍCULOS DEL CONVENIO
  // ============================================
  // IMPORTANTE: Solo capturamos artículos QUE PERTENECEN AL CONVENIO,
  // NO referencias a otras leyes (Estatuto de los Trabajadores, etc.)

  // Patrón 1: Markdown heading ### Art. X o ### Artículo X (más confiable)
  // Ejemplo: "### Art. 18.- Vacaciones"
  const matchH3 = content.match(
    /^###\s+(Art(?:ículo|\.)\s*\d+[º°]?[\.\-]?\s*[^\n]*)/im
  );
  if (matchH3) {
    return normalizeArticulo(matchH3[1].trim());
  }

  // Patrón 2: Negrita markdown **Art. X** o **Artículo X**
  // Ejemplo: "**Art. 8.- Período de prueba**"
  const matchBold = content.match(
    /^\*{1,2}(Art(?:ículo|\.)\s*\d+[º°]?[\.\-]?\s*[^\n*]*)\*{0,2}/im
  );
  if (matchBold) {
    const fullMatch = matchBold[1];
    if (!isReferenciaExterna(fullMatch)) {
      return normalizeArticulo(fullMatch.trim());
    }
  }

  // Patrón 3: Artículo al INICIO de línea (encabezado sin markdown)
  // Ejemplo: "Art. 18.- Vacaciones" o "Artículo 18 - Vacaciones"
  // IMPORTANTE: Debe estar al inicio de línea (^) para evitar capturar referencias internas
  const artStartMatch = content.match(
    /^(Art(?:ículo|\.)\s*(\d+)[º°]?[\.\-]?\s*[–\-:]?\s*([A-ZÁÉÍÓÚÑ][^\n]*))/im
  );
  if (artStartMatch) {
    // Verificar que NO es una referencia a otra ley
    const fullMatch = artStartMatch[1];
    if (!isReferenciaExterna(fullMatch)) {
      return normalizeArticulo(fullMatch.trim());
    }
  }

  // Patrón 3: "14.- Jornada" o "14.- **Jornada**" (formato BOCM)
  // Solo al inicio de línea para evitar falsos positivos
  const bocmMatch = content.match(
    /^(\d+)\.\-\s*\*{0,2}[A-ZÁÉÍÓÚÑ][^\n*]{2,50}\*{0,2}/m
  );
  if (bocmMatch) {
    const num = bocmMatch[1];
    // Solo aceptar si el número es razonable (1-200) para artículos de convenio
    if (parseInt(num) >= 1 && parseInt(num) <= 200) {
      return `Art. ${num}`;
    }
  }

  // Patrón 4: "Artículo 14 - Descansos" (con guión y espacio)
  const articuloConGuion = content.match(
    /^(Artículo\s+(\d+)\s*[\-–]\s*([A-ZÁÉÍÓÚÑ][^\n]*))/im
  );
  if (articuloConGuion) {
    const num = articuloConGuion[2];
    return `Art. ${num}`;
  }

  // Si estamos en una sección de ANEXO, NO heredar artículos anteriores
  // Los anexos no tienen artículos numerados, usar null para que se use la sección
  if (isAnexoSection(currentSeccion)) {
    return null;
  }

  // Si no encuentra nada, heredar del anterior
  return previousArticulo || null;
}

/**
 * Detecta si una referencia es a una ley externa (no al convenio actual)
 */
function isReferenciaExterna(text) {
  const patronesExternos = [
    /estatuto\s+de\s+(los\s+)?trabajadores/i,
    /real\s+decreto/i,
    /ley\s+\d+\/\d+/i,
    /código\s+civil/i,
    /ley\s+orgánica/i,
    /constitución/i,
    /dicho\s+real\s+decreto/i,
    /l\.?o\.?\s+\d+/i // LO 3/2007, etc.
  ];

  return patronesExternos.some(patron => patron.test(text));
}

/**
 * Normaliza el formato del artículo para consistencia
 * Entrada: "Art. 18.- Vacaciones" o "Artículo 18 - Vacaciones"
 * Salida: "Art. 18" (formato corto y consistente)
 */
function normalizeArticulo(articulo) {
  if (!articulo) return null;

  // Extraer solo el número del artículo
  const numMatch = articulo.match(/Art(?:ículo|\.)\s*(\d+)/i);
  if (numMatch) {
    return `Art. ${numMatch[1]}`;
  }

  // Si no podemos normalizar, devolver limpio
  return articulo.replace(/\*+/g, '').trim();
}

function hasTable(content) {
  const tablePattern = /\|[^\n]+\|[\s\S]*?\|[^\n]+\|/;
  return tablePattern.test(content);
}

function isNewArticle(content) {
  // Detecta si el contenido empieza con un nuevo artículo
  // Patrones: "### Art. X", "### Artículo X", "Art. X.-", "X.- Título", "**Art. X"
  return (
    /^###\s+Art/im.test(content) ||
    /^##\s+Art/im.test(content) ||
    /^\*{1,2}Art(?:ículo|\.)\s*\d+/im.test(content) ||
    /^Art(?:ículo|\.)\s*\d+/im.test(content) ||
    /^\d+\.\-\s*\*{0,2}[A-ZÁÉÍÓÚÑ]/m.test(content)
  );
}

/**
 * Divide el contenido en artículos individuales.
 * Busca patrones como "**Art. X.-", "Art. X.-", "## Art. X" etc.
 * y divide el texto en esos puntos.
 */
function splitByArticles(text) {
  const lines = text.split('\n');
  const parts = [];
  let currentPart = '';

  for (const line of lines) {
    const startsNewArticle =
      currentPart.trim() && isNewArticle(line.trimStart());

    if (startsNewArticle) {
      parts.push(currentPart.trim());
      currentPart = line;
      continue;
    }

    currentPart = currentPart ? `${currentPart}\n${line}` : line;
  }

  if (currentPart.trim()) {
    parts.push(currentPart.trim());
  }

  // Si no encontró divisiones, devolver el texto original
  if (parts.length <= 1) {
    return [text];
  }

  return parts;
}

function splitByStructure(markdown) {
  const sections = [];

  // Primero, dividir por artículos (que es la unidad semántica más importante)
  const articleParts = splitByArticles(markdown);

  for (const part of articleParts) {
    // Dentro de cada parte, verificar si tiene headings
    const sectionRegex = /^(#{2,3}\s+[^\n]+)([\s\S]*?)(?=^#{2,3}\s+|$)/gm;
    let match;
    let lastIndex = 0;
    let foundSections = false;

    while ((match = sectionRegex.exec(part)) !== null) {
      foundSections = true;
      if (match.index > lastIndex) {
        const beforeText = part.substring(lastIndex, match.index).trim();
        if (beforeText) sections.push({ type: 'text', content: beforeText });
      }
      sections.push({
        type: 'section',
        header: match[1],
        content: match[0].trim()
      });
      lastIndex = match.index + match[0].length;
    }

    if (foundSections && lastIndex < part.length) {
      const remaining = part.substring(lastIndex).trim();
      if (remaining) sections.push({ type: 'text', content: remaining });
    }

    // Si no encontró headings, añadir la parte como texto
    if (!foundSections && part.trim()) {
      sections.push({ type: 'text', content: part.trim() });
    }
  }

  if (sections.length === 0) {
    return markdown
      .split(/\n\n+/)
      .filter(p => p.trim())
      .map(p => ({ type: 'text', content: p.trim() }));
  }
  return sections;
}

function createChunkObject(
  content,
  number,
  convenioId,
  convenioNombre,
  seccion,
  articulo,
  isTable = false,
  pagina = null
) {
  const tokens = estimateTokens(content);
  const tipo = isTable ? 'tabla_salarial' : detectChunkType(content);
  return {
    contenido: content,
    metadata: {
      convenio_id: convenioId,
      convenio_nombre: convenioNombre,
      numero_chunk: number,
      tokens: tokens,
      seccion: seccion,
      articulo: articulo,
      tipo: tipo,
      tiene_tabla: isTable,
      pagina: typeof pagina === 'number' ? pagina : null,
      total_chunks: 0
    }
  };
}

function getOverlap(text) {
  if (!text || text.length < OVERLAP_CHARS) return '';
  const endPortion = text.substring(text.length - OVERLAP_CHARS * 1.5);
  const sentenceEnd = endPortion.lastIndexOf('. ');
  if (sentenceEnd > 0) return endPortion.substring(sentenceEnd + 2);
  const spaceIndex = endPortion.indexOf(' ');
  if (spaceIndex > 0) return endPortion.substring(spaceIndex + 1);
  return endPortion;
}

// ============================================
// FUNCIÓN PRINCIPAL DE CHUNKING
// ============================================

function chunkMarkdown(markdown, convenioId, convenioNombre, options) {
  // options: { pagina, startChunkNumber, seccionInicial, articuloInicial }
  // - pagina: número de página del PDF para todos los chunks generados en esta llamada
  // - startChunkNumber: numeración global (chunks de páginas anteriores ya consumen IDs)
  // - seccionInicial / articuloInicial: heredados de la página anterior para no resetear
  //   metadata cuando una sección/artículo cruza el corte de página
  const opts = options || {};
  const pagina = typeof opts.pagina === 'number' ? opts.pagina : null;
  const chunks = [];
  let chunkNumber = typeof opts.startChunkNumber === 'number' ? opts.startChunkNumber : 0;
  let currentSeccion = opts.seccionInicial || null;
  let currentArticulo = opts.articuloInicial || null;
  // Track del artículo asociado al chunk que se está acumulando
  let chunkArticulo = null;
  let chunkSeccion = null;
  const sections = splitByStructure(markdown);
  let currentChunk = '';
  let currentTokens = 0;

  for (const section of sections) {
    const sectionContent = section.content || section;
    const sectionTokens = estimateTokens(sectionContent);

    // Extraer sección y artículo de la sección ACTUAL
    const tempSeccion = extractSeccion(sectionContent, currentSeccion);
    if (tempSeccion) currentSeccion = tempSeccion;
    // Pasar la sección actual para detectar si estamos en un ANEXO
    const tempArticulo = extractArticulo(sectionContent, currentArticulo, currentSeccion);
    // Si estamos en anexo, tempArticulo será null y NO heredamos el anterior
    if (tempArticulo !== undefined) currentArticulo = tempArticulo;

    if (hasTable(sectionContent)) {
      // Guardar chunk anterior con SU artículo (no el actual)
      if (currentChunk.trim()) {
        const articuloDelChunk = extractArticulo(currentChunk, chunkArticulo, chunkSeccion || currentSeccion);
        const minTokensRequeridos = articuloDelChunk
          ? MIN_TOKENS_ARTICULO
          : MIN_TOKENS;
        if (currentTokens >= minTokensRequeridos) {
          chunks.push(
            createChunkObject(
              currentChunk.trim(),
              ++chunkNumber,
              convenioId,
              convenioNombre,
              chunkSeccion || currentSeccion,
              articuloDelChunk,
              false,
              pagina
            )
          );
        }
        currentChunk = '';
        currentTokens = 0;
      }
      // Tabla usa el artículo actual
      if (sectionTokens <= MAX_TOKENS * 1.5) {
        chunks.push(
          createChunkObject(
            sectionContent,
            ++chunkNumber,
            convenioId,
            convenioNombre,
            currentSeccion,
            currentArticulo,
            true,
            pagina
          )
        );
      } else {
        const lines = sectionContent.split('\n');
        let tableChunk = '';
        let tableTokens = 0;
        for (const line of lines) {
          const lineTokens = estimateTokens(line);
          if (tableTokens + lineTokens > MAX_TOKENS && tableChunk) {
            chunks.push(
              createChunkObject(
                tableChunk.trim(),
                ++chunkNumber,
                convenioId,
                convenioNombre,
                currentSeccion,
                currentArticulo,
                true,
                pagina
              )
            );
            tableChunk = line + '\n';
            tableTokens = lineTokens;
          } else {
            tableChunk += line + '\n';
            tableTokens += lineTokens;
          }
        }
        if (tableChunk.trim())
          chunks.push(
            createChunkObject(
              tableChunk.trim(),
              ++chunkNumber,
              convenioId,
              convenioNombre,
              currentSeccion,
              currentArticulo,
              true,
              pagina
            )
          );
      }
      chunkArticulo = null;
      chunkSeccion = null;
      continue;
    }

    // Si es un nuevo artículo y ya tenemos contenido, SIEMPRE cerrar el chunk anterior.
    // Los artículos son unidades semánticas y deben mantenerse separados.
    // Usamos MIN_TOKENS_ARTICULO (más bajo) si el chunk contiene un artículo identificado.
    if (isNewArticle(sectionContent) && currentChunk.trim()) {
      const articuloDelChunk = extractArticulo(currentChunk, chunkArticulo, chunkSeccion || currentSeccion);
      // Si el chunk tiene un artículo identificado, usar umbral más bajo
      const minTokensRequeridos = articuloDelChunk
        ? MIN_TOKENS_ARTICULO
        : MIN_TOKENS;

      if (currentTokens >= minTokensRequeridos) {
        chunks.push(
          createChunkObject(
            currentChunk.trim(),
            ++chunkNumber,
            convenioId,
            convenioNombre,
            chunkSeccion || currentSeccion,
            articuloDelChunk,
            false,
            pagina
          )
        );
      }
      // Siempre iniciar nuevo chunk con el artículo actual (no fusionar artículos distintos)
      currentChunk = sectionContent;
      currentTokens = sectionTokens;
      chunkArticulo = currentArticulo;
      chunkSeccion = currentSeccion;
      continue;
    }

    if (currentTokens + sectionTokens <= TARGET_TOKENS) {
      // Si es el inicio del chunk, guardar el artículo de esta sección
      if (!currentChunk) {
        chunkArticulo = currentArticulo;
        chunkSeccion = currentSeccion;
      }
      currentChunk += (currentChunk ? '\n\n' : '') + sectionContent;
      currentTokens += sectionTokens;
      continue;
    }

    if (sectionTokens >= MIN_TOKENS && sectionTokens <= MAX_TOKENS) {
      // Guardar chunk anterior con SU artículo
      if (currentChunk.trim()) {
        const articuloDelChunk = extractArticulo(currentChunk, chunkArticulo, chunkSeccion || currentSeccion);
        const minTokensRequeridos = articuloDelChunk
          ? MIN_TOKENS_ARTICULO
          : MIN_TOKENS;
        if (currentTokens >= minTokensRequeridos) {
          chunks.push(
            createChunkObject(
              currentChunk.trim(),
              ++chunkNumber,
              convenioId,
              convenioNombre,
              chunkSeccion || currentSeccion,
              articuloDelChunk,
              false,
              pagina
            )
          );
        }
      }
      // La sección actual va como chunk independiente con su propio artículo
      chunks.push(
        createChunkObject(
          sectionContent,
          ++chunkNumber,
          convenioId,
          convenioNombre,
          currentSeccion,
          currentArticulo,
          false,
          pagina
        )
      );
      currentChunk = '';
      currentTokens = 0;
      chunkArticulo = null;
      chunkSeccion = null;
      continue;
    }

    if (sectionTokens > MAX_TOKENS) {
      // Guardar chunk anterior con SU artículo
      if (currentChunk.trim()) {
        const articuloDelChunk = extractArticulo(currentChunk, chunkArticulo, chunkSeccion || currentSeccion);
        const minTokensRequeridos = articuloDelChunk
          ? MIN_TOKENS_ARTICULO
          : MIN_TOKENS;
        if (currentTokens >= minTokensRequeridos) {
          chunks.push(
            createChunkObject(
              currentChunk.trim(),
              ++chunkNumber,
              convenioId,
              convenioNombre,
              chunkSeccion || currentSeccion,
              articuloDelChunk,
              false,
              pagina
            )
          );
        }
        currentChunk = '';
        currentTokens = 0;
      }
      // Iniciar nuevo chunk con el artículo de esta sección
      chunkArticulo = currentArticulo;
      chunkSeccion = currentSeccion;

      const paragraphs = sectionContent.split(/\n\n+/);
      for (const para of paragraphs) {
        const paraTokens = estimateTokens(para);
        if (currentTokens + paraTokens <= TARGET_TOKENS) {
          currentChunk += (currentChunk ? '\n\n' : '') + para;
          currentTokens += paraTokens;
        } else {
          if (currentChunk.trim()) {
            const articuloDelChunk = extractArticulo(
              currentChunk,
              chunkArticulo,
              chunkSeccion || currentSeccion
            );
            const minTokensRequeridos = articuloDelChunk
              ? MIN_TOKENS_ARTICULO
              : MIN_TOKENS;
            if (currentTokens >= minTokensRequeridos) {
              chunks.push(
                createChunkObject(
                  currentChunk.trim(),
                  ++chunkNumber,
                  convenioId,
                  convenioNombre,
                  chunkSeccion || currentSeccion,
                  articuloDelChunk,
                  false,
                  pagina
                )
              );
            }
          }
          const overlap = getOverlap(currentChunk);
          currentChunk = overlap + (overlap ? '\n\n' : '') + para;
          currentTokens = estimateTokens(currentChunk);
          // Mantener el artículo para chunks que continúan
        }
      }
    }
  }

  // Último chunk de la página - usar umbral más bajo si contiene artículo
  if (currentChunk.trim()) {
    const articuloDelChunk = extractArticulo(currentChunk, chunkArticulo, chunkSeccion || currentSeccion);
    const minTokensRequeridos = articuloDelChunk
      ? MIN_TOKENS_ARTICULO
      : MIN_TOKENS;

    if (currentTokens >= minTokensRequeridos) {
      chunks.push(
        createChunkObject(
          currentChunk.trim(),
          ++chunkNumber,
          convenioId,
          convenioNombre,
          chunkSeccion || currentSeccion,
          articuloDelChunk,
          false,
          pagina
        )
      );
    }
  }

  // Devolver chunks + estado para que la siguiente página herede contexto
  return {
    chunks,
    lastChunkNumber: chunkNumber,
    seccionFinal: currentSeccion,
    articuloFinal: currentArticulo
  };
}

// ============================================
// EJECUCIÓN PRINCIPAL
// ============================================

// Leemos directamente del nodo 'Save md in supabase1' (PATCH con Prefer: return=representation
// devuelve un array con el row del convenio). No usamos $input porque el nodo previo
// (Notify Progress Markdown) tiene continueOnFail y puede pasar un objeto de error.
const savedData = $('Save md in supabase1').first().json;
const convenioData = Array.isArray(savedData) ? savedData[0] : savedData;

if (!convenioData || !convenioData.id) {
  throw new Error(
    'No se pudo obtener el ID del convenio guardado. Data: ' +
      JSON.stringify(savedData)
  );
}

const convenioId = convenioData.id;
const convenioNombre = convenioData.nombre;
const markdown = convenioData.markdown_completo || '';

if (!markdown || markdown.length < 100) {
  throw new Error(
    'Markdown vacío o muy corto para procesar. Longitud: ' + markdown.length
  );
}

// I1.10: Si 'Extract and clean md1' produjo el array `pages` (formato LlamaParse /result/json),
// chunkeamos página por página y propagamos `metadata.pagina`. Si no lo produjo (fallback al
// formato antiguo), chunkeamos el markdown completo como una sola "página" sin número.
const extracted = $('Extract and clean md1').first().json;
const pages = Array.isArray(extracted && extracted.pages) ? extracted.pages : null;

let allChunks = [];
if (pages && pages.length > 0) {
  let runningChunkNumber = 0;
  let inheritedSeccion = null;
  let inheritedArticulo = null;
  for (const page of pages) {
    const mdPage = (page && page.md) ? page.md : '';
    if (!mdPage || mdPage.trim().length === 0) continue;
    const result = chunkMarkdown(mdPage, convenioId, convenioNombre, {
      pagina: typeof page.page === 'number' ? page.page : null,
      startChunkNumber: runningChunkNumber,
      seccionInicial: inheritedSeccion,
      articuloInicial: inheritedArticulo
    });
    allChunks = allChunks.concat(result.chunks);
    runningChunkNumber = result.lastChunkNumber;
    inheritedSeccion = result.seccionFinal;
    inheritedArticulo = result.articuloFinal;
  }
} else {
  // Fallback sin información de página
  const result = chunkMarkdown(markdown, convenioId, convenioNombre, {
    pagina: null,
    startChunkNumber: 0,
    seccionInicial: null,
    articuloInicial: null
  });
  allChunks = result.chunks;
}

const totalChunks = allChunks.length;
allChunks.forEach(c => (c.metadata.total_chunks = totalChunks));

const stats = {
  total_chunks: allChunks.length,
  avg_tokens: allChunks.length > 0
    ? Math.round(allChunks.reduce((sum, c) => sum + c.metadata.tokens, 0) / allChunks.length)
    : 0,
  min_tokens: allChunks.length > 0
    ? Math.min(...allChunks.map(c => c.metadata.tokens))
    : 0,
  max_tokens: allChunks.length > 0
    ? Math.max(...allChunks.map(c => c.metadata.tokens))
    : 0,
  con_tablas: allChunks.filter(c => c.metadata.tiene_tabla).length,
  con_pagina: allChunks.filter(c => typeof c.metadata.pagina === 'number').length,
  tipos: {}
};

allChunks.forEach(c => {
  stats.tipos[c.metadata.tipo] = (stats.tipos[c.metadata.tipo] || 0) + 1;
});

return allChunks.map((chunk, index) => ({
  json: {
    contenido: chunk.contenido,
    convenio_id: chunk.metadata.convenio_id,
    metadata: chunk.metadata,
    ...(index === 0 ? { chunking_stats: stats } : {})
  }
}));

// Obtener todos los chunks generados
const chunks = $input.all();

// Preparar array para pasar al siguiente nodo (Generate Embeddings)
const allChunks = chunks.map(item => ({
  convenio_id: item.json.convenio_id,
  contenido: item.json.contenido,
  metadata: item.json.metadata
}));

// Obtener stats del primer chunk (si existe)
const stats = chunks[0]?.json?.chunking_stats || {
  total_chunks: chunks.length,
  avg_tokens: 0,
  min_tokens: 0,
  max_tokens: 0
};

return [{
  json: {
    chunks: allChunks,
    total_chunks: allChunks.length,
    stats: stats,
    convenio_id: chunks[0]?.json?.convenio_id
  }
}];

// ============================================
// NODO: Prepare Batch for OpenAI
// TIPO: Code (JavaScript)
// FASE: I1.8
// POSICIÓN: Después de "Prepare Chunks for Insert"
// ============================================

// Obtener datos del input
const inputData = $input.first().json;
const chunks = inputData.chunks;

// Validar que hay chunks
if (!chunks || chunks.length === 0) {
  throw new Error('No hay chunks para generar embeddings');
}

// Preparar textos para embedding
const textos = chunks.map(c => c.contenido);

console.log(`Preparando ${chunks.length} chunks para OpenAI Embeddings API...`);

// Retornar payload separado para OpenAI y metadata interna
return [{
  json: {
    // Payload limpio para OpenAI (solo campos requeridos por la API)
    openai_payload: {
      input: textos,
      model: 'text-embedding-3-small',
      encoding_format: 'float'
    },

    // Metadatos internos (NO se envían a OpenAI)
    _chunks_original: chunks,
    _total_chunks: chunks.length,
    _convenio_id: inputData.convenio_id,
    _stats: inputData.stats
  }
}];

// ============================================
// NODO: Merge Embeddings with Chunks
// TIPO: Code (JavaScript)
// FASE: I1.8
// POSICIÓN: Después de "HTTP Request OpenAI Embeddings"
// ============================================

// Obtener respuesta de OpenAI del nodo HTTP anterior
const inputItem = $input.first();
if (!inputItem) {
  throw new Error('No se recibió respuesta del nodo HTTP de OpenAI');
}
const openAIResponse = inputItem.json;

// Obtener chunks originales que pasamos desde "Prepare Batch for OpenAI"
const prepareNodeItem = $('Prepare Batch for OpenAI').first();
if (!prepareNodeItem) {
  throw new Error(
    'No se encontraron datos del nodo "Prepare Batch for OpenAI"'
  );
}
const prepareNode = prepareNodeItem.json;
const chunks = prepareNode._chunks_original;
const convenioId = prepareNode._convenio_id;

if (!chunks || !Array.isArray(chunks)) {
  throw new Error('Chunks originales no encontrados o formato inválido');
}

// Validar que OpenAI retornó los embeddings
if (!openAIResponse.data || !Array.isArray(openAIResponse.data)) {
  throw new Error('Respuesta inválida de OpenAI API: falta campo "data"');
}

const embeddings = openAIResponse.data;

// Validar que hay chunks para procesar
if (!chunks || chunks.length === 0) {
  throw new Error('No hay chunks para combinar con embeddings');
}

// Validar que la cantidad coincide
if (embeddings.length !== chunks.length) {
  throw new Error(
    `Mismatch en embeddings: ${chunks.length} chunks pero ${embeddings.length} embeddings recibidos`
  );
}

// Combinar chunks con sus embeddings (defensivamente)
const chunksWithEmbeddings = chunks.map((chunk, index) => ({
  ...chunk,
  embedding: (embeddings[index] && embeddings[index].embedding) || null
}));

// Validar que al menos un embedding tiene la dimensión correcta (1536 para text-embedding-3-small)
const firstNonEmptyEmbedding = chunksWithEmbeddings.find(c =>
  Array.isArray(c.embedding)
);

if (!firstNonEmptyEmbedding) {
  throw new Error(
    'No se encontraron embeddings válidos. Todos los chunks tienen embeddings nulos o indefinidos.'
  );
}

if (firstNonEmptyEmbedding.embedding.length !== 1536) {
  throw new Error(
    `Embedding dimension incorrecta: esperado 1536, recibido ${firstNonEmptyEmbedding.embedding.length}`
  );
}

// Advertir si hay chunks sin embeddings
const chunksWithoutEmbeddings = chunksWithEmbeddings.filter(
  c => !Array.isArray(c.embedding)
);
if (chunksWithoutEmbeddings.length > 0) {
  console.warn(
    `⚠️ ${chunksWithoutEmbeddings.length} chunks sin embeddings válidos`
  );
}

// Calcular estadísticas de uso
const usage = openAIResponse.usage || {};
const embeddingUsage = {
  total_tokens: usage.total_tokens || 0,
  prompt_tokens: usage.prompt_tokens || 0,
  chunks_processed: chunks.length,
  model: openAIResponse.model || 'text-embedding-3-small',
  estimated_cost_usd: ((usage.total_tokens || 0) / 1000000) * 0.02 // $0.02 por 1M tokens
};

console.log(`✓ Embeddings generados exitosamente:`);
console.log(`  - Chunks procesados: ${embeddingUsage.chunks_processed}`);
console.log(`  - Tokens consumidos: ${embeddingUsage.total_tokens}`);
console.log(
  `  - Coste estimado: $${embeddingUsage.estimated_cost_usd.toFixed(6)}`
);

// Preparar array para insert en Supabase con validación de metadata
const insertData = chunksWithEmbeddings
  .map((chunk, index) => {
    // Validar que el chunk tiene metadata válida
    if (!chunk.metadata || typeof chunk.metadata !== 'object') {
      console.warn(
        `⚠️ Chunk ${index} carece de metadata válida, usando valores por defecto`
      );
      return {
        convenio_id: chunk.convenio_id,
        contenido: chunk.contenido,
        chunk_index: index, // Usar índice del array como fallback
        metadata: { numero_chunk: index, warning: 'metadata_missing' },
        embedding: chunk.embedding
      };
    }

    // Validar que numero_chunk existe
    const chunkIndex =
      typeof chunk.metadata.numero_chunk === 'number'
        ? chunk.metadata.numero_chunk
        : index; // Fallback al índice si no existe

    if (typeof chunk.metadata.numero_chunk !== 'number') {
      console.warn(
        `⚠️ Chunk ${index} carece de numero_chunk, usando índice ${index}`
      );
    }

    return {
      convenio_id: chunk.convenio_id,
      contenido: chunk.contenido,
      chunk_index: chunkIndex,
      metadata: chunk.metadata,
      embedding: chunk.embedding // IMPORTANTE: Incluir el embedding
    };
  })
  .filter(chunk => chunk !== null); // Filtrar chunks nulos si hubiese alguno

// Contar chunks con embeddings válidos de 1536 dimensiones
const validEmbeddingsCount = insertData.filter(
  item =>
    item.embedding &&
    Array.isArray(item.embedding) &&
    item.embedding.length === 1536
).length;

console.log(
  `✓ Preparados ${insertData.length} chunks para inserción en Supabase`
);

// Log condicional basado en embeddings válidos
if (validEmbeddingsCount === insertData.length) {
  console.log(`  - Todos los chunks tienen embeddings de dimensión 1536`);
} else {
  console.log(
    `  - ${validEmbeddingsCount}/${insertData.length} chunks con embeddings válidos de 1536 dimensiones`
  );
  console.log(
    `  - ⚠️ ${insertData.length - validEmbeddingsCount} chunks con embeddings faltantes o inválidos`
  );
}

return [{
  json: {
    chunks: insertData,
    total_chunks: insertData.length,
    embedding_usage: embeddingUsage,
    convenio_id: convenioId
  }
}];

// ============================================
// NODO: Chunks Branch Complete
// Pasar confirmación de que la rama de chunks terminó
// ============================================

const chunksData = $('Merge Embeddings with Chunks').first().json;

console.log('✓ Rama de chunks completada: ' + chunksData.total_chunks + ' chunks insertados');

return [{
  json: {
    branch: 'chunks',
    status: 'completed',
    total_chunks: chunksData.total_chunks,
    timestamp: Date.now()
  }
}];

// Leer la respuesta de LlamaParse directamente del nodo upstream
// (no usamos $input porque Notify Progress Parsing se interpone y
// con continueOnFail podría enviar una respuesta-error).
const llamaParseResult = $('Get Markdown Result').first().json;

// ============================================
// NORMALIZACIÓN DE PÁGINAS
// ============================================
// El endpoint /result/json devuelve { pages: [{ page, md, text }], job_metadata }.
// Si por cualquier motivo viene el formato viejo (.markdown / .text), construimos
// un array de una sola página para mantener compatibilidad downstream.

function cleanMd(text) {
  if (!text) return '';
  return String(text)
    .replace(/\r\n/g, '\n')          // Normalizar line endings
    .replace(/\n{3,}/g, '\n\n')      // Normalizar múltiples saltos
    .trim();
}

let rawPages = Array.isArray(llamaParseResult.pages) ? llamaParseResult.pages : [];

if (rawPages.length === 0) {
  // Fallback: formato antiguo /result/markdown
  const legacyMd = llamaParseResult.markdown || llamaParseResult.text || '';
  if (legacyMd && legacyMd.trim().length > 0) {
    rawPages = [{ page: 1, md: legacyMd }];
  }
}

if (rawPages.length === 0) {
  throw new Error('No se pudo extraer el markdown de LlamaParse. Respuesta vacía.');
}

// Limpiar y normalizar cada página. LlamaParse usa 'md' para el markdown de la página
// y 'page' para el número (1-indexed). Si falta 'page', inferimos por el índice.
const pages = rawPages
  .map((p, idx) => ({
    page: typeof p.page === 'number' ? p.page : idx + 1,
    md: cleanMd(p.md || p.text || '')
  }))
  .filter(p => p.md.length > 0);

if (pages.length === 0) {
  throw new Error('Todas las páginas extraídas por LlamaParse están vacías.');
}

// Reconstruir markdown_completo concatenando páginas en orden.
// Mantener este campo para no romper consumidores aguas abajo (Heuristic Score,
// Claude Classifier, Save md in supabase1, perfil JSON…).
const markdown_completo = pages.map(p => p.md).join('\n\n');

// Obtener datos del webhook (están dentro de body)
const webhookData = $('Webhook').first().json.body;

// Retornar datos estructurados
return {
  json: {
    markdown_completo,
    longitud: markdown_completo.length,
    pages,                          // [{ page, md }] — usado por 'Chunk Markdown' para asignar metadata.pagina
    total_pages: pages.length,
    convenio_id: webhookData.convenio_id,
    nombre: webhookData.nombre_archivo,
    // Campos opcionales (pueden no venir en el payload)
    ambito: webhookData.ambito || null,
    fecha_vigencia: webhookData.fecha_vigencia || null
  }
};

// ============================================
// NODO: Heuristic Score (Capa 3 de validación)
// FUNCIÓN: Scoring rápido por keywords. Si score muy bajo y visibilidad=publico,
//          podemos rechazar sin gastar Claude.
// ============================================

const upstream = $('Extract and clean md1').first().json;
const markdown = (upstream.markdown_completo || '').toLowerCase();
const webhookBody = $('Webhook').first().json.body || {};
const visibilidad = webhookBody.visibilidad || 'privado';

const KEYWORDS = [
  'convenio', 'colectivo', 'salario', 'jornada', 'categoría profesional',
  'categoria profesional', 'vacaciones', 'artículo', 'articulo',
  'boe', 'código convenio', 'codigo convenio', 'regcon',
  'antigüedad', 'antiguedad', 'horas extraordinarias', 'pagas extra',
  'mesa negociadora', 'acuerdo', 'condiciones de trabajo', 'trabajador'
];

let score = 0;
const hits = [];
for (const kw of KEYWORDS) {
  if (markdown.includes(kw)) {
    score += 1;
    hits.push(kw);
  }
}

// Si el documento es manifiestamente no laboral y se quiere público, rechazo temprano.
const HEURISTIC_REJECT_THRESHOLD = 2;
const earlyReject = visibilidad === 'publico' && score < HEURISTIC_REJECT_THRESHOLD;

return [{
  json: {
    markdown_completo: upstream.markdown_completo,
    convenio_id: upstream.convenio_id,
    nombre: upstream.nombre,
    visibilidad,
    heuristic_score: score,
    heuristic_hits: hits,
    heuristic_early_reject: earlyReject
  }
}];

// ============================================
// NODO: Prepare Classifier Request (Capa 2)
// FUNCIÓN: Construye payload Anthropic para Claude Haiku 4.5
// ============================================

const upstream = $('Heuristic Score').first().json;

// Truncar a ~12000 caracteres (~3000 tokens) para abaratar la llamada.
const MAX_CHARS = 12000;
const snippet = (upstream.markdown_completo || '').slice(0, MAX_CHARS);

const SYSTEM_PROMPT = `Eres un clasificador estricto de documentos laborales españoles.
Dado el texto inicial de un documento, debes determinar a qué categoría pertenece.
Categorías permitidas:
- convenio_colectivo
- boletin_oficial (BOE/BOCM/DOG... con contenido laboral)
- acuerdo_empresa
- acta_mesa_negociadora
- contrato_individual
- nomina
- otro_laboral (manual interno, política RR.HH., reglamento)
- no_laboral

Responde ÚNICAMENTE con un JSON válido, sin texto antes ni después, con esta forma exacta:
{ "categoria": "...", "confianza": 0.0, "indicios": ["..."] }
Donde "confianza" es un número entre 0 y 1.`;

const userPrompt = `Texto del documento (primeros ${snippet.length} caracteres):\n\n${snippet}`;

const payload = {
  model: 'claude-haiku-4-5-20251001',
  max_tokens: 256,
  temperature: 0,
  system: [
    { type: 'text', text: SYSTEM_PROMPT, cache_control: { type: 'ephemeral' } }
  ],
  messages: [{ role: 'user', content: userPrompt }]
};

return [{
  json: {
    payload,
    convenio_id: upstream.convenio_id,
    nombre: upstream.nombre,
    visibilidad: upstream.visibilidad,
    markdown_completo: upstream.markdown_completo,
    heuristic_score: upstream.heuristic_score,
    heuristic_hits: upstream.heuristic_hits,
    heuristic_early_reject: upstream.heuristic_early_reject
  }
}];

// ============================================
// NODO: Parse Classification (Capa 2)
// FUNCIÓN: Parsea la respuesta de Claude, junta con la heurística y decide
//          si el documento es aceptable según la visibilidad solicitada.
// ============================================

const http = $input.first().json;
const prep = $('Prepare Classifier Request').first().json;

// Categorías admisibles para visibilidad pública
const PUBLIC_OK = new Set([
  'convenio_colectivo',
  'boletin_oficial',
  'acuerdo_empresa',
  'acta_mesa_negociadora'
]);
const MIN_CONFIDENCE_PUBLIC = 0.7;
const MIN_CONFIDENCE_PRIVATE = 0.5;

let classification = { categoria: 'desconocido', confianza: 0, indicios: [] };
let classifierError = null;

if (http && http.error) {
  classifierError = http.error.message || 'Error desconocido en clasificador';
} else {
  try {
    const responseText = http?.content?.[0]?.text || '';
    // Limpieza por si Claude devuelve fences
    let cleaned = responseText.trim();
    if (cleaned.startsWith('```json')) cleaned = cleaned.slice(7);
    else if (cleaned.startsWith('```')) cleaned = cleaned.slice(3);
    if (cleaned.endsWith('```')) cleaned = cleaned.slice(0, -3);
    classification = JSON.parse(cleaned.trim());
  } catch (e) {
    classifierError = 'No se pudo parsear la respuesta del clasificador: ' + e.message;
  }
}

// Decisión final
const { categoria, confianza } = classification;
const visibilidad = prep.visibilidad || 'privado';

let accepted = false;
let rejectReason = null;

if (prep.heuristic_early_reject) {
  rejectReason = `El documento no parece laboral (heuristic_score=${prep.heuristic_score}) y se ha solicitado visibilidad pública.`;
} else if (classifierError) {
  // Fail-open en privado, fail-closed en público
  if (visibilidad === 'publico') {
    rejectReason = 'No se pudo clasificar el documento y se ha solicitado visibilidad pública: ' + classifierError;
  } else {
    accepted = true;
  }
} else if (visibilidad === 'publico') {
  if (PUBLIC_OK.has(categoria) && confianza >= MIN_CONFIDENCE_PUBLIC) {
    accepted = true;
  } else {
    rejectReason = `Para visibilidad pública solo se admiten convenios, boletines oficiales o acuerdos sectoriales. Detectado: ${categoria} (confianza ${confianza}).`;
  }
} else {
  // privado: aceptar todo salvo no_laboral con confianza alta
  if (categoria === 'no_laboral' && confianza >= MIN_CONFIDENCE_PRIVATE) {
    rejectReason = 'El documento no parece laboral. Si crees que es un error, vuelve a intentarlo con otro PDF.';
  } else {
    accepted = true;
  }
}

const clasificacion = {
  categoria: classification.categoria || null,
  confianza: classification.confianza ?? null,
  indicios: classification.indicios || [],
  heuristic_score: prep.heuristic_score,
  heuristic_hits: prep.heuristic_hits,
  modelo: 'claude-haiku-4-5-20251001',
  classifier_error: classifierError
};

return [{
  json: {
    convenio_id: prep.convenio_id,
    nombre: prep.nombre,
    visibilidad,
    markdown_completo: prep.markdown_completo,
    accepted,
    reject_reason: rejectReason,
    clasificacion
  }
}];

// ============================================
// NODO: Prepare Claude Request (v2 - Perfil Enriquecido)
// FASE: I1.9
// FUNCIÓN: Preparar payload para llamada a Claude API
// ============================================
// CAMBIOS v2:
// - Extraer TODAS las categorías profesionales (no solo principales)
// - Añadir sinónimos de categorías
// - Añadir salarios por tipo de establecimiento
// - Añadir mapeo de establecimientos a clases
// ============================================

const MODEL = 'claude-sonnet-4-5';
const MAX_OUTPUT_TOKENS = 16384;
const TEMPERATURE = 0;
const MAX_INPUT_CHARS = 250000;

const SYSTEM_PROMPT = `Eres un experto en derecho laboral espanol especializado en convenios colectivos.

Tu tarea es analizar el texto completo de un convenio colectivo y extraer un JSON estructurado con TODA la informacion relevante para calcular condiciones laborales (salarios, jornada, complementos, etc.).

REGLAS ESTRICTAS:
1. Solo extrae datos que aparezcan EXPLICITAMENTE en el texto. Nunca inventes ni supongas valores.
2. Si un dato no aparece en el convenio, omite ese campo del JSON. No pongas null ni valores inventados.
3. Los salarios deben ser EXACTOS tal como aparecen en las tablas del convenio, sin redondear.
4. Cita el articulo del convenio donde aparece cada dato siempre que sea posible.
5. Si hay ambiguedad en un dato, incluyelo en el array "notas_extraccion" explicando la ambiguedad.
6. Responde UNICAMENTE con el JSON. Sin texto antes ni despues. Sin bloques de codigo markdown.
7. El JSON debe ser valido y parseable directamente.
8. IMPORTANTE: Extrae TODAS las categorias profesionales que aparezcan en las tablas salariales, no solo las principales.
9. VALORES POSIBLES OBLIGATORIO: El JSON DEBE incluir el campo "valores_posibles". Este campo es un objeto cuyas claves son EXACTAMENTE las mismas que aparecen en "variables_criticas" (mismo nombre, mismo formato snake_case). Para cada variable critica debes incluir su array de valores posibles:
   - Si la variable es categorica (tipo_contrato, turno_trabajo, etc.): incluye los valores del convenio o defaults sectoriales si no aparecen explicitamente.
   - Si la variable es numerica continua (edad, antiguedad): incluye un array con el rango como strings, ej: ["0-5 anos", "6-10 anos", "11-20 anos", "mas de 20 anos"].
