) {
  throw new Error(
    "Upstream node 'Extract and clean md1' returned no data or is missing required fields: markdown_completo, convenio_id, nombre"
  );
}

const markdownData = upstreamItem.json;
const markdown = markdownData.markdown_completo;
const convenioId = markdownData.convenio_id;
const convenioNombre = markdownData.nombre;

if (!markdown || markdown.trim().length === 0) {
  throw new Error('No hay markdown del convenio para extraer perfil');
}

// Truncar markdown muy largo para reducir latencia (anexos administrativos al final suelen ser prescindibles)
let markdownForClaude = markdown;
let truncated = false;
if (markdown.length > MAX_INPUT_CHARS) {
  markdownForClaude = markdown.slice(0, MAX_INPUT_CHARS) + '\n\n[...documento truncado por longitud...]';
  truncated = true;
}

console.log(
  `Preparando request para Claude: ${convenioNombre || convenioId} (${markdown.length} chars${truncated ? `, truncado a ${MAX_INPUT_CHARS}` : ''})`
);

const userPrompt = buildUserPrompt(markdownForClaude);
const requestStartTime = Date.now();

// Preparar payload para el nodo HTTP
