  }];
}

const rawResponse = inputData.raw_response;
const convenioId = inputData.convenio_id;
const convenioNombre = inputData.convenio_nombre;
const claudeUsage = inputData.claude_usage;

if (!rawResponse) {
  throw new Error('No hay respuesta de Claude para validar');
}

const cleanedJson = cleanJsonResponse(rawResponse);
let perfil;

try {
  perfil = JSON.parse(cleanedJson);
} catch (parseError) {
  // Intentar extraer JSON usando brace-matching
  const firstBrace = cleanedJson.indexOf('{');

  if (firstBrace !== -1) {
    // Implementar brace-matching para extraer el primer objeto JSON válido
    let braceCount = 0;
    let endIndex = -1;
    let inString = false;
    let escapeNext = false;

    for (let i = firstBrace; i < cleanedJson.length; i++) {
      const char = cleanedJson[i];

      // Manejar escape characters
      if (escapeNext) {
        escapeNext = false;
        continue;
      }

      if (char === '\\') {
        escapeNext = true;
        continue;
      }

      // Manejar strings (ignorar braces dentro de strings)
      if (char === '"') {
        inString = !inString;
        continue;
      }

      if (inString) continue;

      // Contar braces fuera de strings
      if (char === '{') {
        braceCount++;
      } else if (char === '}') {
        braceCount--;
        if (braceCount === 0) {
          endIndex = i + 1;
          break;
        }
      }
    }

    if (endIndex !== -1) {
      const extractedJson = cleanedJson.substring(firstBrace, endIndex);
      try {
        perfil = JSON.parse(extractedJson);
        console.log('⚠ JSON extraído usando brace-matching');
      } catch (e) {
        // Debug log con contenido sanitizado
        const sanitizedPreview = cleanedJson.substring(0, 100).replace(/[^\x20-\x7E]/g, '?');
        console.log(`Debug: Parse error after brace-matching. Error: ${parseError.message}. Preview: ${sanitizedPreview}...`);
        throw new Error(`Invalid JSON from Claude: ${parseError.message}`);
      }
    } else {
      const sanitizedPreview = cleanedJson.substring(0, 100).replace(/[^\x20-\x7E]/g, '?');
      console.log(`Debug: No matching closing brace found. Preview: ${sanitizedPreview}...`);
      throw new Error('No valid JSON found in Claude response');
    }
  } else {
    const sanitizedPreview = cleanedJson.substring(0, 100).replace(/[^\x20-\x7E]/g, '?');
    console.log(`Debug: No opening brace found. Preview: ${sanitizedPreview}...`);
    throw new Error('No valid JSON found in Claude response');
  }
}

console.log('✓ JSON parseado correctamente');

// Normalizar esquema: garantizar que los campos opcionales SIEMPRE existan
// con un valor por defecto coherente. Claude omite campos cuando el convenio
// no los menciona (regla 2 del system prompt), pero el consumer espera un
// esquema estable.
const SCHEMA_DEFAULTS = {
  horas_extra: null,
  variables_especificas: {},
  mapeo_establecimientos: {},
  periodo_prueba: [],
  vacaciones: null,
  tablas_salariales: null,
  complementos: [],
  notas_extraccion: [],
  valores_posibles: {}
};
const normalizedKeys = [];
for (const [key, defaultValue] of Object.entries(SCHEMA_DEFAULTS)) {
  if (!(key in perfil)) {
    perfil[key] = defaultValue;
    normalizedKeys.push(key);
  }
}
if (normalizedKeys.length > 0) {
  console.log(`⚠ Esquema normalizado: añadidas ${normalizedKeys.length} key(s) faltantes con default: ${normalizedKeys.join(', ')}`);
}

const missingFields = REQUIRED_FIELDS.filter(f => !perfil[f]);
if (missingFields.length > 0) console.log(`⚠ Campos faltantes: ${missingFields.join(', ')}`);

const allWarnings = [];

if (Array.isArray(perfil.categorias_profesionales)) {
  perfil.categorias_profesionales.forEach((cat, i) => allWarnings.push(...validateCategoria(cat, i)));
  console.log(`✓ ${perfil.categorias_profesionales.length} categorías profesionales`);
} else {
  perfil.categorias_profesionales = [];
  allWarnings.push('categorias_profesionales no es un array o no existe');
}

// Reconciliar con valores_posibles.categoria_profesional: si Claude omite
// categorías por tablas fragmentadas, las añadimos como entrada mínima.
const _vp = perfil.valores_posibles || {};
const _catsPosibles = Array.isArray(_vp.categoria_profesional) ? _vp.categoria_profesional : [];
if (_catsPosibles.length > 0) {
  const _norm = (s) => String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
  const _existentes = new Set(perfil.categorias_profesionales.map(c => _norm(c.nombre)));
  perfil.categorias_profesionales.forEach(c => { if (Array.isArray(c.sinonimos)) c.sinonimos.forEach(s => _existentes.add(_norm(s))); });
  let _added = 0;
  for (const _v of _catsPosibles) {
    if (!_existentes.has(_norm(_v))) {
      perfil.categorias_profesionales.push({ nombre: _v });
      _existentes.add(_norm(_v));
      _added++;
    }
  }
  if (_added > 0) {
    const _msg = `Reconciliación: añadidas ${_added} categoría(s) faltantes desde valores_posibles.categoria_profesional`;
    allWarnings.push(_msg);
    console.log(`⚠ ${_msg}`);
  }
}

if (Array.isArray(perfil.complementos)) {
  perfil.complementos.forEach((comp, i) => allWarnings.push(...validateComplemento(comp, i)));
  console.log(`✓ ${perfil.complementos.length} complementos`);
}

if (Array.isArray(perfil.variables_criticas)) {
  console.log(`✓ Variables críticas: ${perfil.variables_criticas.join(', ')}`);
}

// Validate coherence between variables_criticas and valores_posibles
if (Array.isArray(perfil.variables_criticas)) {
  const valoresPosibles = perfil.valores_posibles || {};
  const keysVP = Object.keys(valoresPosibles);
  const missing = perfil.variables_criticas.filter(v => !valoresPosibles.hasOwnProperty(v));
  const extra = keysVP.filter(k => !perfil.variables_criticas.includes(k));
  if (missing.length > 0) {
    const warnMsg = `⚠ variables_criticas sin entrada en valores_posibles: ${missing.join(', ')}`;
    console.log(warnMsg);
    allWarnings.push(warnMsg);
  }
  if (extra.length > 0) {
    console.log(`⚠ valores_posibles con claves extra (no en variables_criticas): ${extra.join(', ')}`);
  }
  if (missing.length === 0 && keysVP.length > 0) {
    console.log(`✓ valores_posibles coherente con variables_criticas (${keysVP.length} claves)`);
  }
  if (!perfil.valores_posibles) {
    const warnMsg = '⚠ El perfil no tiene campo valores_posibles - requiere reindexado';
    console.log(warnMsg);
    allWarnings.push(warnMsg);
  }
}

const validationResult = {
  is_valid: missingFields.length === 0,
  missing_fields: missingFields,
  warnings: allWarnings,
  stats: {
    categorias: Array.isArray(perfil.categorias_profesionales) ? perfil.categorias_profesionales.length : 0,
    complementos: Array.isArray(perfil.complementos) ? perfil.complementos.length : 0,
    variables_criticas: Array.isArray(perfil.variables_criticas) ? perfil.variables_criticas.length : 0,
    tiene_jornada: !!perfil.jornada,
    tiene_horas_extra: !!perfil.horas_extra,
    tiene_periodo_prueba: Array.isArray(perfil.periodo_prueba) && perfil.periodo_prueba.length > 0,
    tiene_vacaciones: !!perfil.vacaciones,
    tiene_tablas_salariales: !!perfil.tablas_salariales
  }
};

console.log(`✓ Validación: ${validationResult.is_valid ? 'OK' : 'CON CAMPOS FALTANTES'}`);

return [{
  json: {
    perfil_data: perfil,
    convenio_id: convenioId,
    convenio_nombre: convenioNombre,
    validation: validationResult,
    claude_usage: claudeUsage
  }
}];

// ============================================
// NODO: Prepare Supabase Request
// FASE: I1.9
// ============================================

const inputData = $input.first().json;

// Si la validación marcó error (rama falló), pasar sin insertar
if (!inputData.perfil_data) {
  console.log('⚠ Sin perfil_data para insertar, saltando upsert');
  return [{
    json: {
      skip_upsert: true,
      perfil_id: null,
      convenio_id: null,
      convenio_nombre: inputData.convenio_nombre,
      operation: 'skipped',
      validation: inputData.validation,
      claude_usage: inputData.claude_usage
    }
  }];
}

const perfilData = inputData.perfil_data;
const convenioNombre = inputData.convenio_nombre;
const validation = inputData.validation;
const claudeUsage = inputData.claude_usage;

// Obtener UUID real del convenio
const convenioData = $('Save md in supabase1').first().json;
const convenioUuid = Array.isArray(convenioData) ? convenioData[0].id : convenioData.id;

if (!convenioUuid) {
  throw new Error('No se pudo obtener UUID del convenio');
}

console.log(`Preparando upsert perfil: ${convenioNombre} (${convenioUuid})`);

// Preparar payload para INSERT
const insertPayload = {
  convenio_id: convenioUuid,
  perfil_data: perfilData
};

return [{
  json: {
    skip_upsert: false,
    convenio_uuid: convenioUuid,
    insert_payload: insertPayload,
    convenio_nombre: convenioNombre,
    validation: validation,
    claude_usage: claudeUsage
  }
}];

// ============================================
// NODO: Upsert Perfil Supabase
// FASE: I1.9
// FUNCIÓN: Procesar respuesta de Supabase
// ============================================

const prepareData = $('Prepare Supabase Request').first().json;

// Si se saltó el upsert
if (prepareData.skip_upsert) {
  console.log('⚠ Upsert saltado (sin perfil_data)');
  return [{
    json: {
      perfil_id: null,
      convenio_id: null,
      convenio_nombre: prepareData.convenio_nombre,
      operation: 'skipped',
      validation: prepareData.validation || { stats: {}, is_valid: false },
      claude_usage: prepareData.claude_usage
    }
  }];
}

const insertData = $input.first().json;
const convenioNombre = prepareData.convenio_nombre;
const validation = prepareData.validation || { stats: {}, is_valid: false };
const claudeUsage = prepareData.claude_usage;
const convenioUuid = prepareData.convenio_uuid;

// Check si el nodo HTTP anterior falló
if (insertData.error) {
  console.log('⚠ Error al insertar perfil: ' + (insertData.error.message || JSON.stringify(insertData.error)));
  throw new Error('Error al guardar perfil en Supabase: ' + (insertData.error.message || ''));
}

const savedData = insertData;
const savedPerfil = Array.isArray(savedData) ? savedData[0] : savedData;

console.log(`✓ Perfil guardado correctamente (upsert)`);
console.log(`  Categorías: ${validation?.stats?.categorias || 0} | Complementos: ${validation?.stats?.complementos || 0}`);

return [{
  json: {
    perfil_id: savedPerfil.id,
    convenio_id: convenioUuid,
    convenio_nombre: convenioNombre,
    operation: 'upserted',
    validation: validation,
    claude_usage: claudeUsage
  }
}];

// ============================================
// NODO: Determine Final Estado
// FUNCIÓN: Decide si el convenio termina como 'activo' o 'activo_sin_perfil'
//          según si el perfil Claude se generó correctamente.
// ============================================

let operation = 'skipped';
let perfilData = null;
let validation = null;

try {
  const upsert = $('Upsert Perfil Supabase').first().json;
  operation = upsert.operation || 'skipped';
  validation = upsert.validation || null;
} catch {
  // Si Upsert Perfil Supabase falló en runtime, asumimos sin perfil
  operation = 'skipped';
}

try {
  perfilData = $('Validate Perfil JSON').first().json.perfil_data || null;
} catch {
  perfilData = null;
}

const webhookBody = $('Webhook').first().json.body;
const convenioId = webhookBody.convenio_id;

// Si NO se hizo upsert del perfil o el perfil no es válido, marcar como activo_sin_perfil.
// El RAG (chunks) sigue funcionando pero el calculador salarial se debe deshabilitar.
const hasValidProfile = operation === 'upserted' && perfilData;
const estado = hasValidProfile ? 'activo' : 'activo_sin_perfil';

return [{
  json: {
    convenio_id: convenioId,
    estado,
    nombre_oficial: perfilData?.convenio || null,
    nombre_corto: perfilData?.nombre_corto || null,
    ambito_territorial: perfilData?.ambito_territorial || null,
    ambito: perfilData?.ambito || null,
    codigo_regcon: perfilData?.codigo_convenio || null,
    has_valid_profile: hasValidProfile,
    validation
  }
}];

// Notify progress (stage=analyzing, 70%) sin romper el dataflow.
// IMPORTANTE: este nodo reemite $input intacto para que el siguiente nodo
// reciba los datos del nodo previo a este (no la respuesta del webhook).

const url = $env.SUPABASE_URL + '/functions/v1/webhook-progress';
const convenioId = $('Webhook').first().json.body.convenio_id;
const body = {
  convenio_id: convenioId,
  stage: 'analyzing',
  progress: 70,
  message: 'Analizando el contenido…',
};

try {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url,
    headers: {
      'Content-Type': 'application/json',
      'X-Webhook-Secret': 'wp_secret_a7f3e9b2c8d4e5f6',
    },
    body,
    json: true,
  });
  console.log('[Notify analyzing] ok:', JSON.stringify(res));
} catch (err) {
  // No interrumpir el workflow si el webhook falla
  console.error('[Notify analyzing] error:', err.message || String(err));
}

// Reemitir el input INTACTO
return $input.all();

